def transform(grid):
    rows = len(grid)
    cols = len(grid[0])
    background = grid[0][0]
    fill_color = 4

    output = [row[:] for row in grid]

    # Find all foreground positions
    fg_positions = []
    for r in range(rows):
        for c in range(cols):
            if output[r][c] != background:
                fg_positions.append((r, c))

    if not fg_positions:
        return output

    # Pattern: fill a region that spans the foreground area
    # Find bounding box and fill everything between
    min_r = min(p[0] for p in fg_positions)
    max_r = max(p[0] for p in fg_positions)
    min_c = min(p[1] for p in fg_positions)
    max_c = max(p[1] for p in fg_positions)

    # The fill region seems to be defined by foreground shape + 1 pixel buffer
    # Fill all background in this "expanded" bounding box
    filled_rows = set()
    for r in range(rows):
        fg_in_row = [c for c in range(cols) if output[r][c] != background]
        if fg_in_row:
            # This row has fg - fill between min and max fg cols
            left_fg = min(fg_in_row)
            right_fg = max(fg_in_row)
            for c in range(left_fg - 1, right_fg + 2):
                if 0 <= c < cols and output[r][c] == background:
                    output[r][c] = fill_color
            filled_rows.add(r)

    # Fill rows above the shape (up to 3 rows) with projection
    for r in range(min(0, min_r - 3), max(0, min_r - 1)):
        left_fg = min(p[1] for p in fg_positions)
        for c in range(max(0, left_fg - 1), min(cols, left_fg + 1)):
            if output[r][c] == background:
                output[r][c] = fill_color

    # Diagonal fill from top-left to fill region
    diag_c = min_c - 1
    for r in range(-1, min_r - 1):
        diag_c = diag_c - 1
        if 0 <= diag_c < cols and r >= 0:
            if output[r][diag_c] == background:
                output[r][diag_c] = fill_color

    return output
